                  <button
                    type="button"
                    className="text-primary hover:underline"
                    onClick={() => {
                      if (selectedImportIds.size === filteredImportable.length) {
                        setSelectedImportIds(new Set())
                      } else {
                        setSelectedImportIds(new Set(filteredImportable.map(p => p.id)))
                      }
                    }}
                  >
                    {selectedImportIds.size === filteredImportable.length ? 'Deseleccionar todo' : 'Seleccionar todo'}
                  </button>
                </div>

                {/* Lista */}
                <div className="space-y-1.5">
                  {filteredImportable.map(product => {
                    const checked = selectedImportIds.has(product.id)
                    return (
                      <label
                        key={product.id}
                        className={`flex cursor-pointer items-start gap-3 rounded-md border p-3 transition-colors ${
                          checked ? 'border-primary/30 bg-primary/5' : 'hover:bg-muted/40'
                        }`}
                      >
                        <Checkbox
                          checked={checked}
                          onCheckedChange={(val) => {
                            const next = new Set(selectedImportIds)
                            if (val) next.add(product.id)
                            else next.delete(product.id)
                            setSelectedImportIds(next)
                          }}
                          className="mt-0.5"
                        />
                        <div className="min-w-0 flex-1">
                          <p className="text-sm font-medium leading-tight">{product.name}</p>
                          {product.description && (
                            <p className="mt-0.5 text-xs text-muted-foreground line-clamp-1">{product.description}</p>
                          )}
                          <div className="mt-1 flex flex-wrap gap-2 text-[11px] text-muted-foreground">
                            {product.brand && <span>{product.brand}</span>}
                            {product.sale_price && (
                              <span className="font-medium text-foreground">{formatPrice(product.sale_price)}</span>
                            )}
                          </div>
                        </div>
                      </label>
                    )
                  })}
                </div>
              </>
            )}
          </div>

          <DialogFooter className="shrink-0 gap-2 border-t bg-background px-5 py-3 sm:px-6">
